// Generated by `just generate` from `src/plugins/claudetto/slices/ground/adapters/shared.ts`. Edit the source and run `just generate`.
// The part of the hook and of `check` that they share: read the files, run the check, and write the deny.
// A tool result that is a deny of this check is no source, because it names each claim and a retry would pass on it.

import {
  type Files,
  findUnsourced,
  type Msg,
  PROJECT_FILES,
  refFiles,
} from "../domain/claims.ts";
import { UNSOURCED } from "../prompts.ts";

/** What the caller gives: the text of a file, the text of a file found by its path suffix, and the entries of a folder. */
export interface Io {
  read(path: string): Promise<string | null>;
  list(dir: string): Promise<{ name: string; kind: string }[]>;
}

const HEAD = UNSOURCED({ claims: "" }).split("\n")[0] as string;
const DIRS_MAX = 2000;

/** The text of the first file under `cwd` whose path ends with `file`, with `node_modules` and the dot folders skipped. */
const find = async (io: Io, cwd: string, file: string) => {
  const direct = await io.read(`${cwd}/${file}`);
  if (direct !== null) return direct;
  const queue = [cwd];
  for (let seen = 0; queue.length > 0 && seen < DIRS_MAX; seen++) {
    const dir = queue.shift() as string;
    for (const { name, kind } of await io.list(dir).catch(() => [])) {
      if (kind === "dir" && name !== "node_modules" && !name.startsWith("."))
        queue.push(`${dir}/${name}`);
      if (kind === "file" && `${dir}/${name}`.endsWith(`/${file}`))
        return io.read(`${dir}/${name}`);
    }
  }
  return null;
};

/** The deny text for `text`, or `null` when each claim has a source. `target` is the file that the call changes. */
export const groundDeny = async (
  text: string,
  msgs: readonly Msg[],
  io: Io,
  cwd: string,
  target: { path: string; old?: string | undefined } | null,
): Promise<string | null> => {
  const entries = await Promise.all([
    ...PROJECT_FILES.map(
      async (n) => [n, await io.read(`${cwd}/${n}`)] as const,
    ),
    ...refFiles(text).map(async (n) => [n, await find(io, cwd, n)] as const),
  ]);
  const own = target
    ? `${(await io.read(target.path)) ?? ""}\n${target.old ?? ""}`
    : "";
  const claims = findUnsourced(
    text,
    msgs.map((m) => ({
      ...m,
      results: m.results.filter((r) => !r.includes(HEAD)),
    })),
    Object.fromEntries(entries) as Files,
    own,
  );
  return claims.length > 0
    ? UNSOURCED({ claims: claims.map((c) => `- ${c}`).join("\n") })
    : null;
};
